CREATE TABLE "instalacao" (
	"id" smallint PRIMARY KEY DEFAULT 1 NOT NULL,
	"ambiente" varchar(16) NOT NULL,
	"identidade" text NOT NULL,
	"marcada_em" timestamp with time zone NOT NULL,
	"marcada_por" text NOT NULL,
	CONSTRAINT "ck_instalacao_unica" CHECK (id = 1),
	CONSTRAINT "ck_instalacao_ambiente" CHECK (ambiente IN ('PRODUCAO'))
);
